package com.careerpilot.modules.scheduling.service;

import com.careerpilot.exception.*;
import com.careerpilot.modules.assessment.dto.AttemptResponse;
import com.careerpilot.modules.assessment.entity.*;
import com.careerpilot.modules.assessment.repository.*;
import com.careerpilot.modules.assessment.service.AssessmentService;
import com.careerpilot.modules.auth.entity.User;
import com.careerpilot.modules.notification.email.*;
import com.careerpilot.modules.scheduling.dto.*;
import com.careerpilot.modules.scheduling.entity.*;
import com.careerpilot.modules.scheduling.repository.*;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.Instant;
import java.util.*;

@Service
public class ScheduledExamService {
 private final ScheduledExamRepository exams; private final ScheduledExamRescheduleHistoryRepository history; private final AssessmentRepository assessments; private final AssessmentAttemptRepository attempts; private final AssessmentService assessmentService; private final ApplicationEventPublisher events;
 public ScheduledExamService(ScheduledExamRepository e,ScheduledExamRescheduleHistoryRepository h,AssessmentRepository a,AssessmentAttemptRepository ar,AssessmentService s,ApplicationEventPublisher p){exams=e;history=h;assessments=a;attempts=ar;assessmentService=s;events=p;}
 @Transactional public StudentScheduledExamResponse create(User student,CreateScheduledExamRequest r){Assessment a=assessments.findById(r.assessmentId()).filter(Assessment::isActive).orElseThrow(()->new NotFoundException("ASSESSMENT_NOT_FOUND"));future(r.scheduledStart());if(exams.existsByOwnerIdAndAssessmentIdAndScheduledStart(student.getId(),a.getId(),r.scheduledStart()))throw new ConflictException("DUPLICATE_SCHEDULE");ScheduledExam e=new ScheduledExam();e.setAssessment(a);e.setTitle(a.getTitle());e.setScheduledStart(r.scheduledStart());e.setScheduledEnd(end(r.scheduledStart(),a));e.setCreatedBy(student);e.setOwner(student);e=exams.save(e);publish(ExamNotificationEvent.Type.SCHEDULED,e);return response(e);}
 @Transactional(readOnly=true)public List<StudentScheduledExamResponse>list(User student){return exams.findByOwnerIdOrderByScheduledStartDesc(student.getId()).stream().map(this::response).toList();}
 @Transactional(readOnly=true)public StudentScheduledExamResponse get(User student,UUID id){return response(owned(student,id));}
 @Transactional public StudentScheduledExamResponse reschedule(User student,UUID id,RescheduleExamRequest r){ScheduledExam e=exams.lockOwned(id,student.getId()).orElseThrow(()->new NotFoundException("SCHEDULE_NOT_FOUND"));mutable(e);future(r.scheduledStart());if(exams.existsByOwnerIdAndAssessmentIdAndScheduledStart(student.getId(),e.getAssessment().getId(),r.scheduledStart()))throw new ConflictException("DUPLICATE_SCHEDULE");Instant oldStart=e.getScheduledStart(),oldEnd=e.getScheduledEnd(),newEnd=end(r.scheduledStart(),e.getAssessment());ScheduledExamRescheduleHistory h=new ScheduledExamRescheduleHistory();h.setScheduledExam(e);h.setStudent(student);h.setOldStart(oldStart);h.setOldEnd(oldEnd);h.setNewStart(r.scheduledStart());h.setNewEnd(newEnd);history.save(h);e.setScheduledStart(r.scheduledStart());e.setScheduledEnd(newEnd);e.setRescheduleCount(e.getRescheduleCount()+1);e.setLastRescheduledAt(Instant.now());e.setReminderSentAt(null);e=exams.save(e);publish(ExamNotificationEvent.Type.RESCHEDULED,e);return response(e);}
 @Transactional public StudentScheduledExamResponse cancel(User student,UUID id){ScheduledExam e=exams.lockOwned(id,student.getId()).orElseThrow(()->new NotFoundException("SCHEDULE_NOT_FOUND"));if(e.getStatus()==ScheduledExamStatus.CANCELLED)return response(e);mutable(e);e.setStatus(ScheduledExamStatus.CANCELLED);e.setCancelledAt(Instant.now());e=exams.save(e);publish(ExamNotificationEvent.Type.CANCELLED,e);return response(e);}
 @Transactional public AttemptResponse start(User student,UUID id){ScheduledExam e=exams.lockOwned(id,student.getId()).orElseThrow(()->new NotFoundException("SCHEDULE_NOT_FOUND"));if(e.getStatus()==ScheduledExamStatus.CANCELLED)throw new ConflictException("EXAM_CANCELLED");Instant now=Instant.now();if(now.isBefore(e.getScheduledStart()))throw new ConflictException("EXAM_NOT_STARTED");if(!now.isBefore(e.getScheduledEnd())&&e.getAttempt()==null)throw new ConflictException("EXAM_WINDOW_CLOSED");if(e.getAttempt()!=null)return assessmentService.get(student,e.getAttempt().getId());AttemptResponse created=assessmentService.start(student,e.getAssessment().getId());e.setAttempt(attempts.findById(created.id()).orElseThrow());exams.save(e);return created;}
 private void publish(ExamNotificationEvent.Type type,ScheduledExam e){User u=e.getOwner();Assessment a=e.getAssessment();events.publishEvent(new ExamNotificationEvent(type,new ExamEmailDetails(e.getId(),u.getEmail(),u.getFullName(),a.getTitle(),a.getAssessmentType().name(),e.getScheduledStart(),e.getScheduledEnd(),a.getDurationMinutes(),a.getTotalQuestions())));}
 private ScheduledExam owned(User u,UUID id){return exams.findByIdAndOwnerId(id,u.getId()).orElseThrow(()->new NotFoundException("SCHEDULE_NOT_FOUND"));}private void future(Instant i){if(i==null||!i.isAfter(Instant.now()))throw new ApiException(HttpStatus.BAD_REQUEST,"SCHEDULE_MUST_BE_FUTURE");}private Instant end(Instant start,Assessment a){return start.plusSeconds(a.getDurationMinutes()*60L);}private void mutable(ScheduledExam e){if(e.getStatus()==ScheduledExamStatus.CANCELLED)throw new ConflictException("SCHEDULE_CANCELLED");if(e.getAttempt()!=null)throw new ConflictException("ATTEMPT_ALREADY_STARTED");if(!Instant.now().isBefore(e.getScheduledStart()))throw new ConflictException("SCHEDULE_ALREADY_STARTED");}
 private StudentScheduledExamResponse response(ScheduledExam e){AssessmentAttempt a=e.getAttempt();Instant now=Instant.now();String state;if(e.getStatus()==ScheduledExamStatus.CANCELLED)state="CANCELLED";else if(a!=null&&a.getStatus()==AttemptStatus.SUBMITTED)state="COMPLETED";else if(a!=null&&a.getStatus()==AttemptStatus.IN_PROGRESS)state="IN_PROGRESS";else if(now.isBefore(e.getScheduledStart()))state="UPCOMING";else if(now.isBefore(e.getScheduledEnd()))state="AVAILABLE";else state="MISSED";boolean mutable="UPCOMING".equals(state);return new StudentScheduledExamResponse(e.getId(),e.getAssessment().getId(),e.getAssessment().getTitle(),e.getAssessment().getAssessmentType(),e.getAssessment().getDifficulty(),e.getScheduledStart(),e.getScheduledEnd(),e.getAssessment().getDurationMinutes(),e.getAssessment().getTotalQuestions(),state,e.getRescheduleCount(),"AVAILABLE".equals(state),mutable,mutable,a==null?null:a.getId(),a==null?null:a.getScorePercentage());}
}
